add("LY-008","liuyao",LYs,"方向：负面——危症难回，终凶。占病以官鬼为病、子孙为福神医药：泽天夬之雷天大壮，五爻子孙酉金持世动，子孙动克应爻官鬼寅木，初看福神制鬼似吉；然酉金动化申金为化退神——福神退缩、药力日退，鬼寅木得申月金囚之余荫而待木旺之时反张（寅木在申月虽囚，退神之金无力尽克）。进退神定性：子孙化退即救应后继无力，病先减而后重，终局单判为不愈/危。近段：旬内症状稍缓（子孙动克鬼之效）；远段触发：五爻动化退神指向远段救退病进，远段凶——两段已分判、终局从远段定。应期双层（日档，近病）：窗口为一旬内，主坐标取申日（退神逢值、药力尽退）为转危应点。对象复述：主语为患病者本人，同一。置信：0.66。",
 "卦夬之大壮，五爻子孙酉金世动化申金（卡出自进神退神章）。已载面表：主问占病（危症）已断；余面未载；无锚点，转应核不适用。断项过闸：终凶→子孙指代链→动化退神触发→保留。应期三步：日档；逢值（申日）取、冲实（寅冲申）次舍（冲退神反激鬼）、填实无对象舍。动化定性核对：动化方向——酉化申退神为退向，主定性；反转条件——退神得月建生扶方许缓断，申月酉申同气只助其退势坐实、不翻转。终局反转扫查：化退+鬼待时反张成链，达改判门槛（初判似吉→终局凶）。双闸已执行。",0.66,trig(cm=T,reason="初看子孙动克鬼似吉，因动化退神改定终局为凶，changed_main留痕"))

def main():
    ids=[]
    batches=json.load(open("/home/hatch/workspace/divination/benchmark/phase3/runs/round60/batches.json"))
    for b in ("B04","B05","B06"): ids+=batches[b]
    assert set(ids)==set(P.keys()), (set(ids)^set(P.keys()))
    for cid in ids:
        trad,sys_,pred,core,conf,tr=P[cid]
        basis=(f"tradition: {trad}（逐例读输入卡自带字段自决）\n"
               f"systems_used: {sys_}\n{core}")
        obj={"case_id":cid,"prediction_text":pred,"basis":basis,"confidence":conf,"trigger":tr}
        with open(os.path.join(BASE,cid+".json"),"w",encoding="utf-8") as f:
            json.dump(obj,f,ensure_ascii=False,indent=1)
    # self-verify exact list only
    cnt={"changed_main":0,"reserve_used":0,"disputed":0}; n=0
    for cid in ids:
        o=json.load(open(os.path.join(BASE,cid+".json")))
        assert set(o.keys())=={"case_id","prediction_text","basis","confidence","trigger"}, cid
        assert o["case_id"]==cid and 0<=o["confidence"]<=1
        assert set(o["trigger"].keys())=={"changed_main","reserve_used","disputed","reason"}
        for k in cnt:
            assert isinstance(o["trigger"][k],bool)
            cnt[k]+= 1 if o["trigger"][k] else 0
        n+=1
    print("written",n,"trigger_counts",cnt)
    for b in ("B04","B05","B06"):
        print(b, len(batches[b]), "ok")
if __name__=="__main__": main()
